# Get objectName from the definition already in the flow
python3 -c "
import json
flow = json.load(open('/work/output/artifacts/skill-flow-bellevue-weather-simulated/BellevueWeather/BellevueWeather/BellevueWeather.flow'))
for defn in flow['definitions']:
    if defn['nodeType'] == 'uipath.connector.custom-codereval-openmeteoapis.getcurrentweather':
        for ctx in defn.get('model', {}).get('context', []):
            if ctx['name'] == 'objectName':
                print('objectName:', ctx['value'])
        # also check configuration blob
        form = defn.get('form', {})
        for sect in form.get('sections', []):
            for field in sect.get('fields', []):
                cp = field.get('componentProps', {})
                cd = cp.get('connectorDetail', {})
                if cd.get('configuration'):
                    print('configuration:', cd['configuration'])
"

