{
  "id": "cfee0797-40b2-4e98-87e6-68f58af3403b",
  "version": "1.8",
  "name": "BellevueWeather",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "48989316-b009-4d81-aa7a-a02e2b1dd156",
        "isDefaultEntryPoint": true
