      "id": "getCurrentWeather1",
      "type": "uipath.connector.custom-codereval-openmeteoapis.getcurrentweather",
      "typeVersion": "1.0.0",
      "display": {
        "label": "Get Current Weather"
      },
      "inputs": {}
    },
    {
      "id": "evaluateWeather1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Evaluate Weather"
      },
      "inputs": {
        "script": "var weatherOutput = $vars.getCurrentWeather1.output;\nvar current = weatherOutput && weatherOutput.current_weather;\nvar temperature = current ? current.temperature : null;\nvar weathercode = current ? current.weathercode : null;\nvar windspeed = current ? current.windspeed : null;\nvar isDay = current ? current.is_day : 1;\n// WMO codes 0-2: clear/mainly clear = nice; 3+: clouds/rain/snow = not nice\nvar isGoodCode = weathercode !== null && weathercode <= 2;\nvar isComfortableTemp = temperature !== null && temperature >= 10 && temperature <= 30;\nvar isNiceDay = isGoodCode && isComfortableTemp;\nreturn { temperature: temperature, weathercode: weathercode, windspeed: windspeed, isDay: isDay, isNiceDay: isNiceDay };"
      }
    },
    {
      "id": "isNiceDay1",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Is It a Nice Day?"
      },
      "inputs": {
        "expression": "$vars.evaluateWeather1.output.isNiceDay === true",
        "trueLabel": "Nice Day",
        "falseLabel": "Not Nice"
      }
    },
    {
      "id": "niceMessage1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Nice Day Message"
      },
      "inputs": {
        "script": "var temp = $vars.evaluateWeather1.output.temperature;\nreturn { message: \"Great news! It's a beautiful day in Bellevue, WA! ☀️ The temperature is \" + temp + \"°C with clear skies. Perfect weather for outdoor activities!\" };"
      }
    },
    {
      "id": "notNiceMessage1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Not Nice Day Message"
      },
      "inputs": {
        "script": "var temp = $vars.evaluateWeather1.output.temperature;\nvar code = $vars.evaluateWeather1.output.weathercode;\nvar desc = code >= 95 ? 'thunderstorms' : code >= 80 ? 'rain showers' : code >= 71 ? 'snow' : code >= 51 ? 'rain or drizzle' : code >= 45 ? 'fog' : code >= 3 ? 'cloudy skies' : 'cooler temperatures';\nreturn { message: \"Not the best day in Bellevue, WA today. Expect \" + desc + \" with a temperature of \" + temp + \"°C. Consider staying indoors or bringing an umbrella! ☔\" };"
      }
    },
    {
      "id": "endNice",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End (Nice Day)"
      },
      "outputs": {
        "message": "=js:$vars.niceMessage1.output.message"
      }
    },
    {
      "id": "endNotNice",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End (Not Nice Day)"
      },
      "outputs": {
        "message": "=js:$vars.notNiceMessage1.output.message"
      }
    }
