import json

# Load the existing flow to reuse the id, entryPointId, and definitions we need
flow = json.load(open('/work/output/artifacts/skill-flow-bellevue-weather-simulated/BellevueWeather/BellevueWeather/BellevueWeather.flow'))

# Extract definitions we want to keep
defs_by_type = {d['nodeType']: d for d in flow['definitions']}

# Build the new clean flow
new_flow = {
    "id": flow["id"],
    "version": flow["version"],
    "name": "BellevueWeather",
    "nodes": [
        {
            "id": "start",
            "type": "core.trigger.manual",
            "typeVersion": "1.0",
            "display": {"label": "Manual trigger"},
            "inputs": {
                "entryPointId": flow["nodes"][0]["inputs"]["entryPointId"],
                "isDefaultEntryPoint": True
            }
        },
        {
            "id": "getWeather1",
            "type": "core.action.http.v2",
            "typeVersion": "2.3",
            "display": {"label": "Get Weather"},
            "inputs": {
                "branches": [],
                "timeout": "PT15M",
                "retryCount": 0
            }
        },
        {
            "id": "checkTemp1",
            "type": "core.action.script",
            "typeVersion": "1.0",
            "display": {"label": "Check Temperature"},
            "inputs": {
                "script": "var tempF = $vars.getWeather1.output.body.current_weather.temperature;\nreturn { tempF: tempF, isNiceDay: tempF > 60 };"
            }
        },
        {
            "id": "niceDecision1",
            "type": "core.logic.decision",
            "typeVersion": "1.1",
            "display": {"label": "Nice Day?"},
            "inputs": {
                "expression": "$vars.checkTemp1.output.isNiceDay === true",
                "trueLabel": "Nice Day",
                "falseLabel": "Not Nice"
            }
        },
        {
            "id": "endNice",
            "type": "core.control.end",
            "typeVersion": "1.0",
            "display": {"label": "End"},
            "outputs": {
                "message": {
                    "source": "nice day"
                }
            }
        },
        {
            "id": "endNotNice",
            "type": "core.control.end",
            "typeVersion": "1.0",
            "display": {"label": "End"},
            "outputs": {
                "message": {
                    "source": "bring a jacket"
                }
            }
        }
    ],
    "edges": [
        {"id": "e1", "sourceNodeId": "start", "sourcePort": "output", "sourceHandle": "output", "targetNodeId": "getWeather1", "targetPort": "input"},
        {"id": "e2", "sourceNodeId": "getWeather1", "sourcePort": "default", "sourceHandle": "default", "targetNodeId": "checkTemp1", "targetPort": "input"},
        {"id": "e3", "sourceNodeId": "checkTemp1", "sourcePort": "success", "sourceHandle": "success", "targetNodeId": "niceDecision1", "targetPort": "input"},
        {"id": "e4", "sourceNodeId": "niceDecision1", "sourcePort": "true", "sourceHandle": "true", "targetNodeId": "endNice", "targetPort": "input"},
        {"id": "e5", "sourceNodeId": "niceDecision1", "sourcePort": "false", "sourceHandle": "false", "targetNodeId": "endNotNice", "targetPort": "input"}
    ],
    "definitions": [
        defs_by_type["core.trigger.manual"],
        defs_by_type["core.action.http.v2"],
        defs_by_type["core.action.script"],
        defs_by_type["core.logic.decision"],
        defs_by_type["core.control.end"]
    ],
    "runtime": "maestro",
    "bindings": flow.get("bindings", []),
    "variables": {
        "globals": [
            {
                "id": "message",
                "type": "string",
                "description": "Weather result message",
                "direction": "out"
            }
        ],
        "nodes": []
    },
    "layout": {
        "nodes": {
            "start": {"position": {"x": 0, "y": 0}},
            "getWeather1": {"position": {"x": 0, "y": 0}},
            "checkTemp1": {"position": {"x": 0, "y": 0}},
            "niceDecision1": {"position": {"x": 0, "y": 0}},
            "endNice": {"position": {"x": 0, "y": 0}},
            "endNotNice": {"position": {"x": 0, "y": 0}}
        }
    }
}

with open('/work/output/artifacts/skill-flow-bellevue-weather-simulated/BellevueWeather/BellevueWeather/BellevueWeather.flow', 'w') as f:
    json.dump(new_flow, f, indent=2)
print("written")
PYEOF

